function isSettledCustomizationsNotification(notification, sessionUri) {
  if (!isActionNotification(notification, ActionType.SessionCustomizationsChanged) || getActionEnvelope(notification).channel !== sessionUri) {
    return false;
  }
  return getActionEnvelope(notification).action.customizations.length > 0;
}
