  async function waitForPluginCustomizationUpdate(sessionUri, pluginUri) {
    const notificationHasPluginUpdate = (notification) => {
      if (isSettledCustomizationsNotification(notification, sessionUri)) {
        const action = getActionEnvelope(notification).action;
        if (action.customizations.some(
          (customization) => customization.type === CustomizationType.Plugin && customization.uri === pluginUri
        )) {
          return true;
        }
      }
      if (isActionNotification(notification, ActionType.SessionCustomizationUpdated) && getActionEnvelope(notification).channel === sessionUri) {
        const action = getActionEnvelope(notification).action;
        return action.customization.type === CustomizationType.Plugin && action.customization.uri === pluginUri;
      }
      return false;
    };
    const existingMatch = client.receivedNotifications().find((notification) => notificationHasPluginUpdate(notification));
    if (existingMatch) {
      return;
    }
    await client.waitForNotification((notification) => notificationHasPluginUpdate(notification), NOTIFICATION_TIMEOUT_MS);
  }
